define(["jquery","editor_tiny/editor"],function($,tiny){var pageBuilder={offset:200,menuLinks:null,sections:null,init:function(){pageBuilder.menuLinks=document.querySelectorAll(".mainmenu li");pageBuilder.sections=document.querySelectorAll(".course-details-content > div");if(pageBuilder.menuLinks&&pageBuilder.menuLinks[0]){pageBuilder.menuLinks[0].classList.add("current");pageBuilder.menuLinks.forEach(link=>{link.addEventListener("click",pageBuilder.scrollToSection)})}window.scrollTo(0,0);if(pageBuilder.sections){pageBuilder.sections.forEach(section=>{const sectionY=section.getBoundingClientRect().y;section.setAttribute("data-section-y",sectionY)})}window.addEventListener("scroll",pageBuilder.scrollPage);$("#video-popup-wrapper").click(function(){const youtubeVideo=$("#youtube-video");youtubeVideo.attr("src",youtubeVideo.attr("data-src"));$("#youtube-close").click(function(){youtubeVideo.attr("src","")})});$("#enrollment-comprar-btn").click(function(){const comprarLink=$("#comprar-iframe");comprarLink.attr("src",comprarLink.attr("data-src")+Math.random())})},scrollToSection:function(event){event.preventDefault();const targetId=this.getAttribute("data-action");const targetSection=document.getElementById(targetId);const targetPosition=parseInt(targetSection.getAttribute("data-section-y"))-pageBuilder.offset;window.scrollTo({top:targetPosition,behavior:"smooth"})},scrollPage:function(){const scrollPosition=window.scrollY;$(".kopere_pay_view .enrollment-sticky-top").css("top",$("#header").height());pageBuilder.sections.forEach(section=>{const sectionY=parseInt(section.getAttribute("data-section-y"));if(Math.abs(scrollPosition-sectionY+pageBuilder.offset)<40){pageBuilder.menuLinks.forEach(link=>{link.classList.remove("current")});var element=document.getElementById(`for-${section.id}`);element.classList.add("current")}else{}})},createEditor:function(elementId){tiny.setupForElementId({elementId:elementId,options:JSON.parse($("#tyni_editor_config").val())})}};return pageBuilder});